solution.solution.cpp:
#include <cmath>
#include <cstdint>
#include <deque>

struct Input { std::uint32_t sequence; float moveX; float moveY; };
struct PlayerState { float x; float y; };

PlayerState simulate(PlayerState s, const Input& in, float speed, float dt)
{
    float mx{ in.moveX };
    float my{ in.moveY };
    if (!std::isfinite(mx) || !std::isfinite(my)) { mx = 0; my = 0; }
    const float length{ std::sqrt(mx * mx + my * my) };
    if (length > 1.0f) { mx /= length; my /= length; }
    return { s.x + mx * speed * dt, s.y + my * speed * dt };
}

class PredictedPlayer
{
public:
    PredictedPlayer(PlayerState start, float speed, float dt) : state_{ start }, speed_{ speed }, dt_{ dt } {}

    Input applyInput(float moveX, float moveY)
    {
        const Input in{ ++lastSequence_, moveX, moveY };
        state_ = simulate(state_, in, speed_, dt_);
        pending_.push_back(in);
        return in;
    }

    void onServerState(std::uint32_t lastProcessed, PlayerState authoritative)
    {
        if (lastProcessed < confirmed_) return;
        confirmed_ = lastProcessed;
        while (!pending_.empty() && pending_.front().sequence <= lastProcessed) pending_.pop_front();
        state_ = authoritative;
        for (const Input& in : pending_) state_ = simulate(state_, in, speed_, dt_);
    }

    PlayerState state() const { return state_; }
    std::size_t pending() const { return pending_.size(); }

private:
    PlayerState state_;
    float speed_;
    float dt_;
    std::uint32_t lastSequence_{ 0 };
    std::uint32_t confirmed_{ 0 };
    std::deque<Input> pending_;
};

unitTests:
TEST("the shared movement code") {
    const PlayerState a{ simulate({ 1, 1 }, { 1, 1, -1 }, 4, 0.25f) };
    CHECK_NEAR(a.x, 1.70710678, 1e-5); CHECK_NEAR(a.y, 0.29289322, 1e-5);
    const PlayerState b{ simulate({ 0, 0 }, { 1, 0.5f, 0 }, 10, 0.5f) };
    CHECK_NEAR(b.x, 2.5, 1e-6); CHECK_NEAR(b.y, 0, 1e-6);
    const PlayerState c{ simulate({ 3, 4 }, { 1, 30, 40 }, 10, 1) };
    CHECK_NEAR(c.x, 9, 1e-5); CHECK_NEAR(c.y, 12, 1e-5);
}
TEST("predicting at once") {
    PredictedPlayer p{ { 0, 0 }, 10, 0.5f };
    const Input first{ p.applyInput(1, 0) };
    CHECK_EQ(first.sequence, 1u);
    CHECK_NEAR(p.state().x, 5, 1e-6);
    p.applyInput(1, 0);
    const Input third{ p.applyInput(1, 0) };
    CHECK_EQ(third.sequence, 3u);
    CHECK_NEAR(p.state().x, 15, 1e-6);
    CHECK_EQ(p.pending(), 3u);
}
TEST("reconciling") {
    PredictedPlayer p{ { 0, 0 }, 10, 0.5f };
    for (int i{ 0 }; i < 3; ++i) p.applyInput(1, 0);
    p.onServerState(1, { 5, 0 });
    CHECK_EQ(p.pending(), 2u);
    CHECK_NEAR(p.state().x, 15, 1e-6);
    p.onServerState(2, { 0, 0 });
    CHECK_EQ(p.pending(), 1u);
    CHECK_NEAR(p.state().x, 5, 1e-6);
    p.onServerState(1, { 100, 100 });
    CHECK_NEAR(p.state().x, 5, 1e-6);
    CHECK_NEAR(p.state().y, 0, 1e-6);
    p.applyInput(0, 1);
    CHECK_NEAR(p.state().y, 5, 1e-6);
    p.onServerState(9, { 42, 43 });
    CHECK_EQ(p.pending(), 0u);
    CHECK_NEAR(p.state().x, 42, 1e-6);
    CHECK_NEAR(p.state().y, 43, 1e-6);
}
TEST("the same snapshot twice changes nothing") {
    PredictedPlayer p{ { 0, 0 }, 10, 0.5f };
    for (int i{ 0 }; i < 4; ++i) p.applyInput(0, -1);
    p.onServerState(2, { 0, -10 });
    p.onServerState(2, { 0, -10 });
    CHECK_EQ(p.pending(), 2u);
    CHECK_NEAR(p.state().y, -20, 1e-6);
}

